type Props={workspaceName?:string;onSignOut?:()=>void;reportsHref?:string;workspaceStorageKey?:string;apiBase?:string;request?:(url:string,init?:RequestInit)=>Promise<Response>;org?:string;financialHref?:string;legacyHref?:string;embedded?:boolean;ignoreSheets?:string[];retainFiles?:boolean;financialApiBase?:string;financialRequest?:(url:string,init?:RequestInit)=>Promise<any>;financialStorageKey?:string};
type Status={configured:boolean;provider:string|null;model:string|null;source:string;canConfigure:boolean;credentialStorage:boolean};
